localparam integer TEXT_WIDTH  = TEXT_CHARS * 32;
localparam integer SCROLL_SPAN = H_ACTIVE + TEXT_WIDTH;
reg de_d, vs_d;
reg [9:0] x;
reg [8:0] y;
reg [15:0] frame_count;
reg [11:0] scroll_offset;

// Coordinates refer to the input pixel sampled at each rising edge.
always @(posedge clk or posedge rst) begin
    if (rst) begin
        de_d <= 1'b0;
        vs_d <= 1'b0;
        x <= 10'd0;
        y <= 9'd0;
        frame_count <= 16'd0;
        scroll_offset <= 12'd0;
    end else begin
        de_d <= de;
        vs_d <= vs;
        if (vs_d != vs) begin
            x <= 10'd0;
            y <= 9'd0;
        end else if (de) begin
            x <= x + 10'd1;
        end else begin
            x <= 10'd0;
            if (de_d) begin
                if (y == 9'd479) y <= 9'd0;
                else y <= y + 9'd1;
            end
        end

        // Rising edge only: exactly one motion update opportunity per frame.
        // It occurs in vertical blanking, so the whole next frame is stable.
        if (vs && !vs_d) begin
            if (enable) begin
                if (frame_count == FRAME_DIV - 1) begin
                    frame_count <= 16'd0;
                    if (scroll_offset + STEP_PIXELS >= SCROLL_SPAN)
                        scroll_offset <= scroll_offset + STEP_PIXELS - SCROLL_SPAN;
                    else
                        scroll_offset <= scroll_offset + STEP_PIXELS;
                end else begin
                    frame_count <= frame_count + 16'd1;
                end
            end
        end
    end
end

// Text origin = H_ACTIVE - scroll_offset. This avoids signed coordinates.
wire [12:0] text_space = {3'b000,x} + {1'b0,scroll_offset};
wire [12:0] text_local = text_space - H_ACTIVE;
wire [8:0] text_y = y - 9'd440;
// Native 32x32 font: one font pixel per screen pixel, 2-bit edge coverage.
wire [5:0] char_index = text_local[10:5];
wire [4:0] font_y = text_y[4:0];
wire [4:0] font_x = text_local[4:0];
reg [63:0] row_bits;
always @(posedge clk)row_bits<=subtitle_rom[{char_index[4:0],font_y}];
wire text_region = (text_space >= H_ACTIVE)
                && (text_space < H_ACTIVE + TEXT_WIDTH)
                && (y >= 440 && y < 472);
wire band_on = (y >= 432 && y < 480);
reg [5:0] bit_index;
reg band_d,text_d,enable_d,de_stage,vs_stage;
reg [23:0] rgb_stage;
always @(posedge clk or posedge rst)begin
 if(rst)begin bit_index<=0;band_d<=0;text_d<=0;enable_d<=0;de_stage<=0;vs_stage<=0;rgb_stage<=0;end
 else begin bit_index<={5'd31-font_x,1'b0};band_d<=band_on;text_d<=text_region;enable_d<=enable;de_stage<=de;vs_stage<=vs;rgb_stage<=rgb_in;end
end
wire [1:0] coverage = row_bits[bit_index +: 2];
wire [23:0] dim_rgb = {2'b00,rgb_stage[23:18],
                      2'b00,rgb_stage[15:10],
                      2'b00,rgb_stage[7:2]};
reg [23:0] mixed_rgb;
// Alpha levels 0, 1/4, 3/4, 1. Add/shift only, no divider or multiplier IP.
function [7:0] blend_channel;
    input [7:0] background;
    input [1:0] alpha;
    reg [9:0] sum;
    begin
        case (alpha)
            2'd0: blend_channel = background;
            2'd1: begin
                sum = {2'b00,background} + {1'b0,background,1'b0} + 10'd255;
                blend_channel = sum[9:2];
            end
            2'd2: begin
                sum = {2'b00,background} + 10'd765;
                blend_channel = sum[9:2];
            end
            default: blend_channel = 8'd255;
        endcase
    end
endfunction
always @* begin
    mixed_rgb = rgb_stage;
    if (enable_d && de_stage) begin
        if (band_d) mixed_rgb = dim_rgb;
        if (text_d)
            mixed_rgb = {blend_channel(dim_rgb[23:16],coverage),
                         blend_channel(dim_rgb[15:8],coverage),
                         blend_channel(dim_rgb[7:0],coverage)};
    end
end

// The sideband signals are registered together with the pixel color.
always @(posedge clk or posedge rst) begin
    if (rst) begin
        rgb_out <= 24'd0;
        vs_out <= 1'b0;
        de_out <= 1'b0;
    end else begin
        rgb_out <= mixed_rgb;
        vs_out <= vs_stage;
        de_out <= de_stage;
    end
end
endmodule
